/**
 * 立ち絵のまばたき・口パクの差分（段階46b）。元の表情の絵から目・口のまわりだけを切り抜いた透明な絵（scripts/portrait_parts.py）。
 * 入手元・ライセンスは元の絵と同じ。会話の画面で表情の絵に重ねる（src/data/dialogue.ts の PORTRAIT_PARTS）
 */
const PORTRAIT_PART_FILES: [file: string, from: string, title: string][] = [
  ['akari_blink', 'portrait.akari.laugh', 'あかりの閉じた目（まばたき）'],
  ['akari_talk', 'portrait.akari.worried', 'あかりの開いた口（口パク）'],
  ['hero_talk', 'portrait.hero.surprised', 'ハルトの開いた口（口パク）'],
  ...(['normal', 'proud', 'serious', 'sad', 'smirk', 'flustered'] as const).map(
    (f): [string, string, string] => [`riku_talk_${f}`, `portrait.riku.talk_${f}_src`, `りくの開いた口（口パク。${RIKU_FACE_TITLES[f]}）`],
  ),
  ['hero_blink', 'portrait.hero.blink_src', 'ハルトの閉じた目（まばたき）'],
  ['riku_blink', 'portrait.riku.blink_src', 'りくの閉じた目（まばたき）'],
  // 1-1・1-2 の人たち（2026-10-19）。_l は基本の1枚（1024×1536）に重ねる大きさに広げたもの
  ...(
    [
      ['yuma', 'ゆうま', ['blink', 'blink_l', 'talk']],
      ['fumi', '富美', ['blink', 'blink_l', 'talk', 'talk_l']],
      ['young_riku', '子どものりく', ['blink', 'blink_l', 'talk']],
      ['past_yuma', '写しのゆうま', ['blink', 'blink_l', 'talk']],
      ['past_kiyoshi', '写しの清志', ['blink', 'blink_l', 'talk', 'talk_l']],
      ['young_akari', '子どものあかり', ['blink', 'blink_l', 'talk']],
      ['young_hero', '子どものハルト', ['blink', 'blink_l', 'talk', 'talk_l']],
      ['past_fumi', '写しの富美', ['blink', 'blink_l', 'talk']],
      ['past_hinano', '写しのひなの', ['blink_l']],
      ['kenta', 'けんた', ['blink_l', 'talk_l']],
      ['kai', 'カイ', ['blink_l']],
      ['toya', 'とうや', ['blink', 'talk']],
      ['shiori', 'しおり', ['blink']],
      ['isamu', '勇夫', ['blink', 'talk']],
      ['petra', 'ペトラ', ['blink', 'talk']],
      ['koji', '浩二', ['blink', 'talk']],
      ['chiyo', '千代', ['blink', 'talk']],
      ['kai', 'カイ', ['talk']],
      ['taichi', 'たいち', ['blink', 'talk']],
      ['past_toya', '写しのとうや', ['blink', 'talk']],
      ['past_chiyo', '写しの千代', ['blink', 'talk']],
      ['past_kiku', '写しの菊', ['blink', 'talk']],
      ['past_shiori', '写しのしおり', ['blink']],
      ['past_kenta', '写しのけんた', ['blink', 'talk']],
      ['masaru', '正雄', ['blink', 'talk']],
      ['noboru', '昇平', ['blink', 'talk']],
      ['past_taichi', '写しのたいち', ['blink', 'talk']],
      ['past_masaru', '写しの正雄', ['blink']],
      ['past_koji', '写しの浩二', ['blink', 'talk']],
      ['hinano', 'ひなの', ['blink', 'talk']],
      ['noa', 'ノア', ['blink', 'talk']],
      ['sumi', '寿美', ['blink', 'talk']],
      ['shigeru', '茂雄', ['blink', 'talk']],
      ['past_genzo', '写しの源三', ['blink', 'talk']],
      ['saki', 'さき', ['blink', 'talk']],
    ] as const
  ).flatMap(([who, name, files]) =>
    files.map((f): [string, string, string] => [
      `${who}_${f}`,
      `portrait.${who}.${f.startsWith('blink') ? 'blink' : 'talk'}_src`,
      `${name}の${f.startsWith('blink') ? '閉じた目（まばたき）' : '開いた口（口パク）'}${f.endsWith('_l') ? '（基本の1枚の大きさ）' : ''}`,
    ]),
  ),
  // 早瀬（2026-11-17）：表情ごとの目を閉じた絵と、通常の口を開けた絵から切り抜いた
  ...(['normal', 'thinking', 'wry', 'surprised', 'angry', 'teary'] as const).map(
    (f): [string, string, string] => [`hayase_blink_${f}`, `portrait.hayase.blink_src_${f}`, `早瀬の閉じた目（まばたき。${f} に重ねる）`],
  ),
  ['hayase_talk', 'portrait.hayase.talk_src_normal', '早瀬の開いた口（口パク）'],
  ['hayase_talk_thinking', 'portrait.hayase.talk_src_thinking', '早瀬の開いた口（口パク。考える）'],
  ['hayase_talk_wry', 'portrait.hayase.talk_src_wry', '早瀬の開いた口（口パク。苦笑い）'],
  // みお・小夜子（2026-10-31）
  ['mio_talk', 'portrait.mio.surprised', 'みおの開いた口（口パク）'],
  ['sayoko_blink', 'portrait.sayoko.laugh', '小夜子の閉じた目（まばたき）'],
  ['sayoko_talk', 'portrait.sayoko.surprised', '小夜子の開いた口（口パク）'],
  // みおの閉じた目（2026-10-31）：表情ごとの目を閉じた絵から切り抜いた
  ...(['smile', 'serious', 'surprised', 'thinking', 'worried', 'pout', 'frustrated', 'wry', 'shy', 'teary'] as const).map(
    (f): [string, string, string] => [`mio_blink_${f}`, `portrait.mio.${f}_blink_src`, `みおの閉じた目（まばたき。${f} に重ねる）`],
  ),
];
for (const [file, from, title] of PORTRAIT_PART_FILES) {
  const src = ASSETS.find((a) => a.id === from);
  if (!src) throw new Error(`立ち絵の差分の元の絵がない：${from}`);
  ASSETS.push({
    ...src,
    id: `portrait.part.${file}`,
    title,
    file: `assets/portraits/parts/${file}.webp`,
    // 2026-10-19 からの差分は、元の絵を入れた日
    acquiredAt: src.acquiredAt > '2026-10-11' ? src.acquiredAt : '2026-10-11',
    notes: `${src.title}から切り抜いた（scripts/portrait_parts.py。段階46b）。${src.notes ?? ''}`,
  });
}
